"""Clarify postseal reporting draft only; retain its first generated bytes."""
from common import *
from datetime import datetime,timezone

prior=read(HERE/'REPORT_VALIDATION.json')
verify_item(prior['report']);verify_item(prior['results'])
changes={}
replacements={
    'report.py':('正式及唯一可用单边反事实全部输出与访问记录封存后，才读现有已曝光参考。',
        '全部正式预测与访问记录封存后，才读现有已曝光参考；本轮无可用单边反事实项，未运行反事实。'),
    'FINAL_REVIEW.md':('正式及唯一可用单边反事实全部输出与访问记录封存后，才读现有已曝光参考。',
        '全部正式预测与访问记录封存后，才读现有已曝光参考；本轮无可用单边反事实项，未运行反事实。'),
    'interpretation.py':('这证明当前预测形式与实际重接时距失配，不能证明正确物理区间应该只有60mm，也不能靠截断尺度制造可靠性。',
        '这揭示短窗预测在实际重接时距上未提供可用否决证据；更窄尺度是否物理合理仍UNKNOWN，不能证明正确物理区间应该只有60mm，也不能靠截断尺度制造可靠性。'),
    'INTERPRETATION.md':('这证明当前预测形式与实际重接时距失配，不能证明正确物理区间应该只有60mm，也不能靠截断尺度制造可靠性。',
        '这揭示短窗预测在实际重接时距上未提供可用否决证据；更窄尺度是否物理合理仍UNKNOWN，不能证明正确物理区间应该只有60mm，也不能靠截断尺度制造可靠性。')}
base=HERE/'report_revisions/first_generated'
for name in (*replacements,'REPORT_VALIDATION.json'):
    path=HERE/name;target=base/name;assert not target.exists();target.parent.mkdir(parents=True,exist_ok=True)
    before=path.read_bytes();old_pin=artifact(path);target.write_bytes(before)
    assert target.read_bytes()==before
    if name in replacements:
        old,new=replacements[name];text=path.read_text(encoding='utf-8');assert text.count(old)==1,(name,text.count(old))
        path.write_text(text.replace(old,new),encoding='utf-8')
    changes[name]=dict(old=old_pin,preserved=artifact(target),new=artifact(path))
changes['REPORT_VALIDATION.json']['before_current_report_rebind']=changes['REPORT_VALIDATION.json'].pop('new')
# The interpretation is included verbatim in FINAL_REVIEW, so clarify its copy.
path=HERE/'FINAL_REVIEW.md';old,new=replacements['INTERPRETATION.md'];text=path.read_text(encoding='utf-8');assert text.count(old)==1
path.write_text(text.replace(old,new),encoding='utf-8');changes['FINAL_REVIEW.md']['new']=artifact(path)
m=read(RUN/'METRICS.json');fields=('IDF1','HOTA','AssA','IDSW','FP','FN')
def table(name):return m['feeding_pooled']['metrics'] if name=='Feeding pooled 1471' else m['segments'][name]['metrics']
parsed=[x.split('|')[1:-1] for x in path.read_text(encoding='utf-8').splitlines() if x.startswith('|')]
metrics=[x for x in parsed if len(x)==8 and x[1] in ARMS]
deltas=[x for x in parsed if len(x)==8 and x[1].startswith('Z4Q_DEPTH_VETO−')]
assert len(metrics)==27 and len(deltas)==10
for name,arm,*values in metrics:
    for field,value in zip(fields,values):assert abs(float(value)-table(name)[arm][field])<=5.1e-7
for name,arm,*values in deltas:
    arm=arm.split('−')[1]
    for field,value in zip(fields,values):assert abs(float(value)-(table(name)[ARMS[2]][field]-table(name)[arm][field]))<=5.1e-7
record=HERE/'REPORT_CLARIFICATION_LOG.json'
write_new(record,dict(status='REPORTING_TEXT_CLARIFIED_NO_RESEARCH_CHANGE',utc=datetime.now(timezone.utc).isoformat(),
    changes=changes,old_draft_bytes_retained=True,reason=['No actual counterfactual was available or run.',
        'Wide prediction proxies do not prove a narrower scale would be physically valid.'],
    prediction_score_seal_and_results_unchanged=True,numeric_rows_rechecked=37))
prior.update(report=artifact(path),reporting_clarification=artifact(record))
(HERE/'REPORT_VALIDATION.json').write_text(json.dumps(prior,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
assert read(HERE/'REPORT_VALIDATION.json')['results']==prior['results'];verify_item(prior['results'])
print('POSTSEAL_REPORT_TEXT_CLARIFIED_37_NUMERIC_ROWS_UNCHANGED',flush=True)
